mapper.select:
SELECT checkin_id AS check_in_id, participant_id, action
FROM checkin_logs
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE checkins
SET status = 'CANCELLED', cancelled_at = #{at}, cancelled_by = #{actorUserId},
    cancel_reason = #{reason}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND id = #{checkInId}
  AND status = 'CHECKED_IN'

mapper.select:
SELECT count(*)
FROM checkin_logs
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND participant_id = #{participantId}

SELECT l.id AS log_id, l.checkin_id AS check_in_id, l.action, l.method, l.actor_user_id,
       u.display_name AS actor_display_name, l.reason, l.created_at
FROM checkin_logs l
JOIN users u ON u.id = l.actor_user_id
WHERE l.space_id = #{spaceId} AND l.event_id = #{eventId}
  AND l.participant_id = #{participantId}
ORDER BY l.seq DESC
LIMIT #{page.size} OFFSET #{page.offset}
